static inline uint8_t f32_to_fp8e4m3fn_rne(float f) {
    uint32_t x;
    std::memcpy(&x, &f, sizeof(uint32_t));
    uint32_t sign = (x >> 24) & 0x80u;   // fp8 sign bit in position 7

    // Handle NaN/inf: map to fp8 NaN (0x7F or 0xFF) preserving sign.
    //   fp32 inf is 0x7F800000; fp8 has no inf -> saturate would lose info,
    //   so map inf and nan to fp8 NaN (exp=15, mant=7) with sign.
    // The clamp(min(max(x,-448),448)) upstream guarantees no |inf| reaches here,
    // but handle defensively.
    if ((x & 0x7FFFFFFFu) > 0x7F800000u) {  // NaN
