+  if (scale == 0.0f) {                         // contract: all-zero K, 0 scale
+    for (int d = 0; d < head_dim; ++d) k_dst[d] = 0u;
+    return;
+  }
+  for (int d = 0; d < head_dim; ++d) {
+    float q = x[d] / scale;
+    if (q > 448.0f) q = 448.0f;
+    else if (q < -448.0f) q = -448.0f;
