      {1,   4, 64,  8, 16,  32, 1},   // single-pool (decode-via-prefill)
      {4,   4, 64,  8, 16,  32, 2},
      {16,  4, 64,  8, 16,  32, 2},
      {64,  4, 64,  8, 16,  32, 2},
      {128, 4, 64,  8, 32,  32, 4},
      {256, 4, 64,  8, 32,  32, 4},
      {1,   8, 128, 16, 16, 64, 1},
      {16,  8, 128, 16, 16, 64, 2},
      {64,  8, 128, 16, 32, 64, 2},
      {128, 8, 128, 16, 32, 64, 4},
      {256, 8, 128, 16, 64, 64, 4},
  };
  const int H = 128;

  std::printf("\n=== hip::dsa_kpool_assemble (PREFILL, 1 warp/pool) ===\n");
